/** Native Android screens. No WebView, remote generation, network permission, or API key. */
public class MainActivity extends Activity {
    interface Work { void run() throws Exception; }
    LearningEngine engine;JSONObject labels,summary;LinearLayout root,body;String route="today",selected="math",pendingExport="";EditText lastInput;
    int foreground,muted,background,surface,primary=Color.rgb(67,85,218);boolean saving=false,saveFailed=false;
    String t(String key){return labels==null?key:labels.optString(key,key);} int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    void run(Work w){try{w.run();}catch(Exception e){if(engine==null)startupFailure();else Toast.makeText(this,t("error"),Toast.LENGTH_LONG).show();}}
    void startupFailure(){LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(24),dp(48),dp(24),dp(24));TextView message=new TextView(this);message.setText(R.string.startup_error);message.setTextSize(18);panel.addView(message);Button retry=new Button(this);retry.setText(R.string.startup_retry);retry.setOnClickListener(v->recreate());panel.addView(retry);setContentView(panel);}
    String asset(String name)throws IOException{try(InputStream in=getAssets().open(name)){return read(in);}}
    String read(InputStream in)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] block=new byte[4096];int n;while((n=in.read(block))!=-1){if(out.size()+n>10000000)throw new IOException("Size");out.write(block,0,n);}return new String(out.toByteArray(),StandardCharsets.UTF_8);}
    @Override public void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::handleBack);run(()->{JSONObject catalog=new JSONObject(asset("content.json"));labels=catalog.getJSONObject("labels");String saved=getSharedPreferences("learning",MODE_PRIVATE).getString("state",null);engine=new LearningEngine(catalog,saved);if(saved!=null){try{engine.validate(new JSONObject(saved));}catch(Exception invalid){getSharedPreferences("learning",MODE_PRIVATE).edit().putString("recovery",saved).commit();saveFailed=true;}}route=engine.profile().optBoolean("onboarded")?"today":"onboard";if(b!=null){route=b.getString("route",route);selected=b.getString("selected","math");String result=b.getString("summary");if(result!=null)summary=new JSONObject(result);}if(route.equals("results")&&summary==null)route="today";draw();});}
    @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("route",route);b.putString("selected",selected);if(summary!=null)b.putString("summary",summary.toString());persist();}
    @Override protected void onPause(){super.onPause();persist();}
    // API 33+ registers the native OnBackInvokedDispatcher in onCreate.
    // This override handles only the compatibility path on Android 8-12.
    @android.annotation.SuppressLint("GestureBackNavigation")
    @Override public void onBackPressed(){handleBack();}
    void handleBack(){if(route.equals("today")||route.equals("onboard")){persist();finish();}else{persist();route="today";run(this::draw);}}
    void persist(){if(engine==null||saving)return;saving=true;boolean ok=getSharedPreferences("learning",MODE_PRIVATE).edit().putString("state",engine.state.toString()).commit();saving=false;saveFailed=!ok;if(!ok)Toast.makeText(this,t("error"),Toast.LENGTH_LONG).show();}
    GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    TextView text(LinearLayout box,String value,int size,boolean bold){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(foreground);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);v.setLineSpacing(dp(3),1.12f);v.setPadding(0,dp(5),0,dp(9));box.addView(v);return v;}
    void note(LinearLayout box,String value){TextView v=text(box,value,14,false);v.setTextColor(muted);}
    LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(20),dp(16),dp(20),dp(16));c.setBackground(shape(surface,18));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(10),0,dp(8));body.addView(c,p);return c;}
    Button button(LinearLayout box,String title,boolean main,Work action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextSize(15);b.setMinHeight(dp(50));b.setTextColor(main?Color.WHITE:foreground);b.setBackground(shape(main?primary:(surface==Color.WHITE?Color.rgb(236,240,255):Color.rgb(44,57,86)),12));b.setPadding(dp(14),dp(8),dp(14),dp(8));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(5),0,dp(5));box.addView(b,p);b.setOnClickListener(v->run(action));return b;}
    void localized(LinearLayout box,JSONObject bi)throws JSONException{text(box,bi.getString("de"),17,false);if(engine.profile().getString("language").equals("tr")){TextView tr=text(box,bi.optString("tr",bi.getString("de")),16,false);tr.setTextColor(muted);tr.setTextLocale(new Locale("tr"));}}
    void draw()throws Exception{lastInput=null;boolean dark=engine.profile().optBoolean("dark");foreground=Color.parseColor(dark?"#EDF1FB":"#202C48");muted=Color.parseColor(dark?"#B2BED4":"#65728C");background=Color.parseColor(dark?"#12192A":"#F4F6FB");surface=Color.parseColor(dark?"#1A2438":"#FFFFFF");root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(background);root.setPadding(dp(16),0,dp(16),0);root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets padding=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()|WindowInsets.Type.ime());v.setPadding(dp(16)+padding.left,padding.top,dp(16)+padding.right,padding.bottom);}else v.setPadding(dp(16)+insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),dp(16)+insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});setContentView(root);TextView brand=text(root,engine.catalog.optString("name","KlarLernen"),24,true);brand.setPadding(dp(4),dp(12),0,dp(10));ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(2),dp(10),dp(2),dp(16));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(saveFailed)note(body,t("error"));switch(route){case "onboard":case "profile":profile();break;case "subjects":subjects();break;case "lesson":lesson();break;case "task":task();break;case "results":results();break;case "progress":progress();break;default:today();}if(engine.profile().optBoolean("onboarded")){LinearLayout nav=new LinearLayout(this);for(String key:new String[]{"today","subjects","progress","profile"}){Button b=new Button(this);b.setText(t(key));b.setTextSize(11);b.setAllCaps(false);b.setTextColor(route.equals(key)?primary:muted);b.setMinHeight(dp(56));nav.addView(b,new LinearLayout.LayoutParams(0,dp(56),1));b.setOnClickListener(v->run(()->{persist();route=key;draw();}));}root.addView(nav);} }
    void today()throws Exception{text(body,t("intro"),15,false);String nickname=engine.profile().optString("name");text(body,nickname.isEmpty()?t("tagline"):"Hallo, "+nickname+".",28,true);List<JSONObject> p=engine.plan();JSONObject rec=p.get(0),u=engine.unit(rec.getString("unit"));LinearLayout hero=card();note(hero,engine.profile().getInt("minutes")+" · "+t("daily"));text(hero,u.getString("topic"),24,true);note(hero,rec.getInt("due")>0?t("review"):rec.getInt("wrong")>0?t("planReason")+" ("+rec.getInt("wrong")+")":t("intro"));button(hero,t(engine.active()==null?"start":"continue"),true,()->{engine.begin("practice",null,5,false);route="task";persist();draw();});note(hero,t("offline"));LinearLayout plan=card();text(plan,t("daily"),20,true);for(JSONObject e:p){text(plan,engine.unit(e.getString("unit")).getString("title")+" · 5 min",17,false);}note(plan,t("planReason"));LinearLayout review=card();int count=engine.state.getJSONArray("reviews").length();text(review,t("review")+" · "+count,20,true);if(count>0)button(review,t("review"),false,()->start("review",null,5,false));else note(review,t("empty"));LinearLayout week=card();text(week,t("progress"),20,true);int total=engine.latest().size();note(week,total==0?t("empty"):total+" · "+t("practice"));Calendar c=Calendar.getInstance();for(int i=6;i>=0;i--){Calendar d=(Calendar)c.clone();d.add(Calendar.DAY_OF_YEAR,-i);int n=0;for(JSONObject a:engine.latest()){Calendar x=Calendar.getInstance();x.setTimeInMillis(a.getLong("time"));if(x.get(Calendar.YEAR)==d.get(Calendar.YEAR)&&x.get(Calendar.DAY_OF_YEAR)==d.get(Calendar.DAY_OF_YEAR))n++;}note(week,new java.text.SimpleDateFormat("EEE dd.MM",Locale.GERMAN).format(d.getTime())+"  ·  "+n);}note(body,t("scope"));}
    EditText field(LinearLayout box,String label,String value,boolean multiline){TextView lv=text(box,label,14,true);EditText e=new EditText(this);e.setText(value);e.setTextColor(foreground);e.setTextSize(16);e.setSingleLine(!multiline);e.setMinHeight(dp(multiline?100:52));e.setPadding(dp(10),dp(9),dp(10),dp(9));e.setBackground(shape(surface==Color.WHITE?Color.rgb(246,248,253):Color.rgb(32,42,64),8));e.setContentDescription(label);if(multiline)e.setGravity(Gravity.TOP);box.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
    Spinner select(LinearLayout box,String label,String[] values,int selected){text(box,label,14,true);Spinner s=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values);s.setAdapter(a);s.setSelection(selected);s.setMinimumHeight(dp(52));s.setContentDescription(label);box.addView(s);return s;}
    void profile()throws Exception{JSONObject p=engine.profile();text(body,t(route.equals("onboard")?"intro":"profile"),27,true);note(body,t("guest"));LinearLayout c=card();EditText name=field(c,t("nickname"),p.optString("name"),false);name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(40)});String[] schools={"Gesamtschule","Realschule","Gymnasium","Hauptschule"};Spinner school=select(c,t("school"),schools,Arrays.asList(schools).indexOf(p.getString("school")));note(c,t("grade")+" 10 · NRW");Spinner lang=select(c,t("language"),new String[]{"Deutsch","Deutsch + Türkçe"},p.getString("language").equals("tr")?1:0);Spinner minutes=select(c,t("daily"),new String[]{"10 min","15 min","20 min"},p.getInt("minutes")==10?0:p.getInt("minutes")==15?1:2);EditText date=field(c,t("examDate"),p.optString("date"),false);date.setFocusable(false);date.setOnClickListener(v->{Calendar cal=Calendar.getInstance();new DatePickerDialog(this,(view,y,m,d)->date.setText(String.format(Locale.ROOT,"%04d-%02d-%02d",y,m+1,d)),cal.get(Calendar.YEAR),cal.get(Calendar.MONTH),cal.get(Calendar.DAY_OF_MONTH)).show();});button(c,t("delete")+" · "+t("examDate"),false,()->date.setText(""));text(c,t("subjects"),18,true);List<CheckBox> chosen=new ArrayList<>();for(int i=0;i<engine.units().length();i++){JSONObject u=engine.units().getJSONObject(i);CheckBox cb=new CheckBox(this);cb.setText(u.getString("title"));cb.setTag(u.getString("id"));cb.setTextColor(foreground);cb.setMinHeight(dp(48));cb.setChecked(p.getJSONArray("subjects").toString().contains("\""+u.getString("id")+"\""));chosen.add(cb);c.addView(cb);}CheckBox dark=new CheckBox(this);dark.setText(t("theme")+" · Dunkel");dark.setTextColor(foreground);dark.setChecked(p.optBoolean("dark"));dark.setMinHeight(dp(48));c.addView(dark);button(c,t("save"),true,()->{JSONArray ids=new JSONArray();for(CheckBox cb:chosen)if(cb.isChecked())ids.put(cb.getTag());if(ids.length()==0){Toast.makeText(this,t("subjects"),Toast.LENGTH_SHORT).show();return;}boolean first=!p.optBoolean("onboarded");p.put("name",name.getText().toString().trim()).put("school",school.getSelectedItem()).put("language",lang.getSelectedItemPosition()==1?"tr":"de").put("minutes",new int[]{10,15,20}[minutes.getSelectedItemPosition()]).put("date",date.getText().toString()).put("subjects",ids).put("dark",dark.isChecked()).put("onboarded",true);persist();if(first)new AlertDialog.Builder(this).setTitle(t("diagnostic")).setMessage(t("assessmentInfo")).setPositiveButton(t("diagnostic"),(d,w)->run(()->start("diagnostic",null,6,false))).setNegativeButton(t("continue"),(d,w)->run(()->{route="today";draw();})).setOnCancelListener(d->run(()->{route="today";draw();})).show();else{route="today";draw();}});if(!route.equals("onboard")){LinearLayout data=card();text(data,t("guest"),19,true);note(data,t("dataNotice"));button(data,t("export"),false,()->export(engine.state.toString(2)));button(data,t("import"),false,()->{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("application/json");intent.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,42);});button(data,t("parents"),false,()->{List<JSONObject> attempts=engine.latest();long independent=attempts.stream().filter(a->a.optString("status").equals("correct")&&!a.optBoolean("help")).count();Intent share=new Intent(Intent.ACTION_SEND);share.setType("text/plain");share.putExtra(Intent.EXTRA_TEXT,engine.catalog.getString("name")+"\n"+independent+" / "+attempts.size()+" · "+t("independent")+"\n"+t("guest"));startActivity(Intent.createChooser(share,t("parents")));});button(data,t("delete"),false,()->new AlertDialog.Builder(this).setTitle(t("delete")).setMessage(t("dataNotice")).setPositiveButton(t("delete"),(d,w)->run(()->{engine.state=engine.fresh();persist();route="onboard";draw();})).setNegativeButton(t("back"),null).show());LinearLayout plans=card();text(plans,t("plans"),20,true);note(plans,t("noPayment"));note(plans,"Pro · 5,99 €/Monat · "+t("coming"));}note(body,t("scope"));}
    void subjects()throws Exception{text(body,t("subjects"),28,true);for(int i=0;i<engine.units().length();i++){JSONObject u=engine.units().getJSONObject(i);String id=u.getString("id");LinearLayout c=card();note(c,u.getString("title"));text(c,u.getString("topic"),22,true);note(c,u.getJSONArray("items").length()+" · "+t("practice"));button(c,t("lesson"),true,()->{selected=id;route="lesson";draw();});}LinearLayout coming=card();text(coming,t("coming"),19,true);JSONArray upcoming=engine.catalog.getJSONArray("upcoming");for(int i=0;i<upcoming.length();i++)note(coming,upcoming.getString(i));}
    void lesson()throws Exception{JSONObject u=engine.unit(selected);text(body,u.getString("title"),15,true);text(body,u.getString("topic"),28,true);LinearLayout c=card();text(c,t("overview"),18,true);JSONArray goals=u.getJSONArray("goals");for(int i=0;i<goals.length();i++)text(c,"• "+goals.getString(i),16,false);localized(c,u.getJSONObject("intro"));note(c,t("reviewPending"));button(c,t("overview")+" · "+t("scope"),false,()->new AlertDialog.Builder(this).setTitle(t("scope")).setMessage(u.getString("source")+"\n\n"+t("reviewPending")).setPositiveButton(t("back"),null).show());LinearLayout model=card();text(model,t("animation"),18,true);String[] parts=u.getJSONObject("intro").getString("de").split("(?<=\\.)\\s+");JSONObject positions=engine.state.getJSONObject("lessonPositions");int position=Math.min(parts.length-1,positions.optInt(selected));text(model,parts[position],18,false);note(model,(position+1)+" / "+parts.length);if(position+1<parts.length)button(model,t("next"),false,()->{positions.put(selected,position+1);persist();draw();});LinearLayout practice=card();button(practice,t("practice")+" · 5",true,()->start("practice",selected,5,false));button(practice,t("diagnostic")+" · 3",false,()->start("diagnostic",selected,3,false));note(practice,t("examInfo"));CheckBox timer=new CheckBox(this);timer.setText(t("timer"));timer.setTextColor(foreground);timer.setMinHeight(dp(48));practice.addView(timer);button(practice,t("exam")+" · 5",false,()->start("exam",selected,5,timer.isChecked()));button(practice,t("exam")+" · 10",false,()->start("exam",selected,10,timer.isChecked()));}
    void start(String mode,String unit,int count,boolean timed)throws Exception{engine.begin(mode,unit,count,timed);route="task";persist();draw();}
    void track(EditText input,JSONObject draft,String key){input.setOnFocusChangeListener((v,focus)->{if(focus)lastInput=input;});input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){run(()->{draft.put(key,s.toString());persist();});}public void afterTextChanged(Editable e){}});}
    void task()throws Exception{JSONObject a=engine.active();if(a==null){route="today";today();return;}JSONObject q=engine.current(),d=a.getJSONObject("draft"),e=engine.entry();boolean exam=a.getString("mode").equals("exam")||a.getString("mode").equals("diagnostic"),locked=d.getBoolean("locked");text(body,t(a.getString("mode"))+" · "+engine.unit(e.getString("unit")).getString("title"),14,true);text(body,(a.getInt("index")+1)+" / "+a.getJSONArray("queue").length(),28,true);if(a.optBoolean("timed"))note(body,(System.currentTimeMillis()-a.getLong("started"))/60000+" min");LinearLayout c=card();localized(c,q.getJSONObject("prompt"));if(q.has("expression")){TextView expression=text(c,q.getString("expression").replace("-","−"),28,true);expression.setGravity(Gravity.CENTER);expression.setContentDescription(q.getString("expression"));}String type=q.getString("type");if(type.equals("choice")){JSONArray options=q.getJSONArray("options");for(int i=0;i<options.length();i++){String option=options.getString(i);Button b=button(c,option,d.getString("answer").equals(option),()->{d.put("answer",option);persist();draw();});b.setEnabled(!locked);}}else if(type.equals("order")){JSONArray original=q.getJSONArray("ordered");List<String> list=new ArrayList<>();if(d.getString("answer").isEmpty())for(int i=original.length()-1;i>=0;i--)list.add(original.getString(i));else list.addAll(Arrays.asList(d.getString("answer").split(" → ")));d.put("answer",String.join(" → ",list));for(int i=0;i<list.size();i++){int index=i;String value=list.get(i);text(c,(i+1)+". "+value,17,false);if(i>0){Button b=button(c,"↑ "+value,false,()->{Collections.swap(list,index,index-1);d.put("answer",String.join(" → ",list));persist();draw();});b.setEnabled(!locked);}}}else{EditText answer=field(c,t("answer")+(q.optString("unit").isEmpty()?"":" ("+q.getString("unit")+")"),d.getString("answer"),false);answer.setFilters(new InputFilter[]{new InputFilter.LengthFilter(240)});answer.setEnabled(!locked);lastInput=answer;track(answer,d,"answer");if(type.equals("math")){EditText steps=field(c,t("steps"),d.getString("steps"),true);steps.setFilters(new InputFilter[]{new InputFilter.LengthFilter(4000)});steps.setEnabled(!locked);track(steps,d,"steps");for(String[] row:new String[][]{{"1","2","3","x","="},{"4","5","6","−","/"},{"7","8","9","(",")"},{"0",",","⌫"}}){LinearLayout keys=new LinearLayout(this);for(String value:row){Button key=new Button(this);key.setText(value);key.setAllCaps(false);key.setEnabled(!locked);key.setMinHeight(dp(48));key.setTextColor(foreground);keys.addView(key,new LinearLayout.LayoutParams(0,dp(50),1));key.setOnClickListener(v->{EditText target=lastInput==null?answer:lastInput;int pos=Math.max(0,target.getSelectionStart()),end=Math.max(pos,target.getSelectionEnd());String val=value.equals("−")?"-":value.equals("⌫")?"":value;Editable raw=target.getText();if(value.equals("⌫")&&pos>0)raw.delete(pos-1,end);else raw.replace(pos,end,val);target.requestFocus();});}c.addView(keys);}}}note(c,t("draft"));JSONObject feedback=d.optJSONObject("feedback");if(feedback!=null){String status=feedback.getString("status");text(c,exam&&!status.equals("unsupported")?t("saved"):t(status.equals("correct")?"correct":status.equals("unsupported")?"unsupported":"incorrect"),17,true);if(feedback.optInt("line")>0&&!exam)note(c,t("stepError")+" · "+feedback.getInt("line"));}button(c,t(locked?"next":"check"),true,()->{((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(c.getWindowToken(),0);if(locked){JSONObject result=engine.next();if(result!=null){summary=result;route="results";}}else engine.submit();persist();draw();});button(c,t("skip"),false,()->{JSONObject out=engine.skip();if(out!=null){summary=out;route="results";}persist();draw();});if(exam)note(body,t("examHelp"));else{LinearLayout help=card();Button hb=button(help,t("hint")+" "+d.getInt("hints")+"/3",false,()->{d.put("hints",Math.min(3,d.getInt("hints")+1));persist();draw();});hb.setEnabled(d.getInt("hints")<3);button(help,t("solution"),false,()->{d.put("solution",true);persist();draw();});for(int i=0;i<d.getInt("hints");i++)localized(help,q.getJSONArray("hints").getJSONObject(i));if(d.getBoolean("solution"))localized(help,q.getJSONObject("explanation"));LinearLayout guide=card();text(guide,t("guide"),19,true);note(guide,t("guideInfo"));button(guide,t("lesson"),false,()->{d.put("hints",Math.max(2,d.getInt("hints")));persist();new AlertDialog.Builder(this).setTitle(t("guide")).setMessage(q.getJSONArray("hints").getJSONObject(1).getString(engine.profile().getString("language"))).setPositiveButton(t("back"),(x,w)->run(this::draw)).show();});}button(body,t("end"),false,()->{persist();route="today";draw();});}
    void results()throws Exception{if(summary==null){JSONArray sessions=engine.state.getJSONArray("sessions");if(sessions.length()==0){route="today";today();return;}summary=sessions.getJSONObject(sessions.length()-1);}text(body,t("finished"),27,true);LinearLayout c=card();text(c,summary.getInt("correct")+" / "+summary.getInt("total")+" · "+t("correct"),24,true);note(c,summary.getInt("independent")+" · "+t("independent"));note(c,summary.getInt("help")+" · "+t("helped"));note(c,t(summary.getString("mode").equals("diagnostic")?"assessmentInfo":"enough"));JSONArray results=summary.getJSONArray("results");for(int i=0;i<results.length();i++){JSONObject r=results.getJSONObject(i),q=engine.question(r.getString("unit"),r.getString("questionId"));LinearLayout row=card();text(row,engine.unit(r.getString("unit")).getString("title")+" · "+r.getString("answer"),17,true);localized(row,q.getJSONObject("prompt"));if(q.has("expression"))text(row,q.getString("expression"),18,true);if(!r.optString("steps").isEmpty())note(row,r.getString("steps"));localized(row,q.getJSONObject("explanation"));}if(engine.state.getJSONArray("reviews").length()>0)button(body,t("review"),true,()->start("review",null,5,false));button(body,t("progress"),false,()->{route="progress";draw();});button(body,t("start"),false,()->start("practice",null,5,false));}
    void progress()throws Exception{text(body,t("progress"),28,true);List<JSONObject> attempts=engine.latest();long independent=attempts.stream().filter(a->a.optString("status").equals("correct")&&!a.optBoolean("help")).count();LinearLayout c=card();text(c,independent+" / "+attempts.size()+" · "+t("independent"),24,true);note(c,attempts.isEmpty()?t("empty"):t("enough"));text(c,engine.state.getJSONArray("reviews").length()+" · "+t("review"),18,true);for(int i=0;i<engine.units().length();i++){JSONObject u=engine.units().getJSONObject(i);String id=u.getString("id");int n=0,right=0;for(JSONObject a:attempts)if(a.getString("unit").equals(id)){n++;if(a.getString("status").equals("correct")&&!a.getBoolean("help"))right++;}LinearLayout unit=card();text(unit,u.getString("title"),20,true);note(unit,right+" / "+n+" · "+t("independent"));}JSONArray all=engine.state.getJSONArray("attempts");LinearLayout history=card();text(history,t("history"),20,true);for(int i=all.length()-1;i>=Math.max(0,all.length()-30);i--){JSONObject a=all.getJSONObject(i),q=engine.question(a.getString("unit"),a.getString("questionId"));button(history,engine.unit(a.getString("unit")).getString("title")+" · "+a.getString("answer")+" · "+t(a.getString("status").equals("correct")?"correct":"incorrect"),false,()->new AlertDialog.Builder(this).setTitle(t("history")).setMessage(q.getJSONObject("prompt").getString("de")+"\n"+a.getString("steps")+"\n"+q.getJSONObject("explanation").getString(engine.profile().getString("language"))+"\n"+t(a.optBoolean("help")?"helped":"independent")).setPositiveButton(t("back"),null).show());}}
    void export(String json){pendingExport=json;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("application/json");intent.putExtra(Intent.EXTRA_TITLE,"KlarLernen-Sicherung.json");startActivityForResult(intent,41);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;run(()->{if(request==41){if(pendingExport.isEmpty())pendingExport=engine.state.toString(2);try(OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new IOException();out.write(pendingExport.getBytes(StandardCharsets.UTF_8));}pendingExport="";Toast.makeText(this,t("saved"),Toast.LENGTH_SHORT).show();}else if(request==42){JSONObject restored;try(InputStream in=getContentResolver().openInputStream(data.getData())){if(in==null)throw new IOException();restored=new JSONObject(read(in));}engine.validate(restored);engine.state=restored;persist();route="today";draw();}});}
}

